export function createArena(teams,{id='arena-'+Date.now(),theme='garden',ai=true}={}){const s={id,theme,time:0,limit:180,paused:false,over:false,winner:null,teams:structuredClone(teams),actors:teams.map((t,i)=>({pid:t.pid,x:i?735:225,y:340,aimX:i?225:735,aimY:340,cooldowns:[0,0,0,0],dash:2,dashRefill:0,invuln:0,swapCooldown:0,ai:ai&&i===1,input:{x:0,y:0},nextAI:0})),projectiles:[],effects:[],cover:[{x:390,y:240,r:23,hp:100},{x:570,y:445,r:23,hp:100},{x:590,y:210,r:18,hp:70},{x:370,y:455,r:18,hp:70}],field:{weather:'',weatherTurns:0,sides:Object.fromEntries(teams.map(t=>[t.pid,{hazards:{}}])),seen:{}},seq:0,log:[],pulse:0};for(let i=0;i<2;i++)enterBattle(s.teams[i],s.teams[1-i],s.field,[],()=>.5);return s}
export function arenaInput(s,pid,input){const a=s.actors.find(a=>a.pid===pid);if(!a||!input||s.over||s.paused)return false;a.input={x:clamp(Number(input.x)||0,-1,1),y:clamp(Number(input.y)||0,-1,1)};if(Number.isFinite(input.aimX)&&Number.isFinite(input.aimY)){a.aimX=clamp(input.aimX,0,AW);a.aimY=clamp(input.aimY,0,AH)}return true}
